        }
      ]
    },
    {
      "omurga": true,
      "parcalar": [
        {
          "t": "metin",
          "v": "Öğle molasında kulüp üyeleri büyük bir kaya gölgesinde oturdu. "
        },
        {
          "t": "yoldas",
          "hal": "yalin",
          "yedek": "bir arkadaş"
        },
        {
          "t": "metin",
          "v": " çantasından atıştırmalığını çıkarırken, \"Daha hızlı gitseydik şimdi terasta olurduk,\" dedi. "
        },
        {
          "t": "kahraman",
          "hal": "yalin"
