  v_r := public.okuma_paket_ice_aktar($y033${{
  "paket_surumu": 1,
  "hikaye": {
    "slug": "hr075-okulun-yanlis-anlayan-yapay-zekasi",
    "baslik": "Okulun Yanlış Anlayan Yapay Zekâsı",
    "tur": "mizah",
    "konu": "deyim_gercek_anlam",
    "sinif_alt": 6,
