  v_r := public.okuma_paket_ice_aktar($y047${{
  "paket_surumu": 1,
  "hikaye": {
    "slug": "hr089-beyrekin-sozunun-agirligi",
    "baslik": "Beyrek'in Sözünün Ağırlığı",
    "tur": "fantastik",
    "konu": "soz_vefa_yanlis_anlama",
    "sinif_alt": 7,
    "sinif_ust": 7,
    "okuma_bandi": 3,
    "dunya_tipi": "masalsi",
    "izinli_turler": [
      "ben",
      "arkadas",
      "hayali"
    ],
    "deger_anahtarlari": [
      "D15",
      "D6"
    ],
    "yetiskin_uygun": false,
    "etiketler": {
      "ana_sinif": 7,
      "okuma_zorlugu": 5,
      "kavram_zorlugu": 5,
      "ilgi_egilimi": "ortak",
      "temalar": [
