        "sinif_alt": 7,
        "sinif_ust": 8
      },
      {
        "id": "hr107_onkabul",
        "tur": "kelime",
        "yazim": "önkabul",
        "anlam": "İncelemeden önce kabul edilen görüş.",
        "sinif_alt": 7,
        "sinif_ust": 8
      },
      {
        "id": "hr107_kesin_bilgi",
        "tur": "kelime",
        "yazim": "kesin bilgi",
        "anlam": "Kanıtlarla doğrulanmış, şüphe bırakmayan bilgi.",
        "sinif_alt": 7,
        "sinif_ust": 8
      },
      {
        "id": "hr107_baglam",
        "tur": "kelime",
        "yazim": "bağlamın",
        "anlam": "Bir sözcüğün, cümlenin ya da olayın geçtiği çevre ve durum.",
        "sinif_alt": 7,
        "sinif_ust": 8
      },
      {
        "id": "hr107_cerceve",
        "tur": "kelime",
        "yazim": "çerçeve",
        "anlam": "Bir olayı ya da düşünceyi çevreleyen genel durum.",
        "sinif_alt": 7,
        "sinif_ust": 8
      },
      {
        "id": "hr107_baglamdan_kopuk",
        "tur": "kelime",
        "yazim": "bağlamdan kopuk",
        "anlam": "Çevresinden ayrılmış, nerede ve nasıl kullanıldığı belli olmayan.",
        "sinif_alt": 7,
        "sinif_ust": 8
      },
      {
        "id": "hr107_bakis",
        "tur": "kelime",
        "yazim": "bakış açısına",
        "anlam": "Bir olaya hangi yönden bakıldığı, düşünce açısı.",
        "sinif_alt": 7,
        "sinif_ust": 8
